import os
os.makedirs("system", exist_ok=True)

# ---- blockMeshDict: duct background mesh, 10 mm cells (coarse) ----
x0, x1 = -DUCT_HALF, DUCT_HALF
z0, z1 = Z_DUCT_LO, Z_DUCT_HI
nx = int(round((x1-x0)/0.010)); ny = nx; nz = int(round((z1-z0)/0.010))
blockmesh = f"""FoamFile
{{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      blockMeshDict;
}}
convertToMeters 1;

vertices
(
    ({x0} {x0} {z0})   //0
    ({x1} {x0} {z0})   //1
    ({x1} {x1} {z0})   //2
    ({x0} {x1} {z0})   //3
    ({x0} {x0} {z1})   //4
    ({x1} {x0} {z1})   //5
    ({x1} {x1} {z1})   //6
    ({x0} {x1} {z1})   //7
);

blocks
(
    hex (0 1 2 3 4 5 6 7) ({nx} {ny} {nz}) simpleGrading (1 1 1)
);

edges ();

boundary
(
    inlet
    {{
        type patch;
        faces ( (0 3 2 1) );
    }}
    outlet
    {{
        type patch;
        faces ( (4 5 6 7) );
    }}
    walls
    {{
        type wall;
        faces
        (
            (0 1 5 4)
            (1 2 6 5)
            (2 3 7 6)
            (3 0 4 7)
        );
    }}
);
"""
open("system/blockMeshDict","w").write(blockmesh)

controldict = """FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
application     snappyHexMesh;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1;
deltaT          1;
writeControl    timeStep;
writeInterval   1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
"""
open("system/controlDict","w").write(controldict)
print("blockMesh cells:", nx, ny, nz, "->", nx*ny*nz, "cells")
print("wrote system/blockMeshDict, system/controlDict")

snappy = """FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      snappyHexMeshDict;
}
castellatedMesh true;
snap            true;
addLayers       false;

geometry
{
    barrel
    {
        type triSurfaceMesh;
        file "barrel.stl";
    }
    fins
    {
        type triSurfaceMesh;
        file "fins.stl";
    }
    head
    {
        type triSurfaceMesh;
        file "head.stl";
    }
}

castellatedMeshControls
{
    maxLocalCells 1000000;
    maxGlobalCells 4000000;
    minRefinementCells 10;
    maxLoadUnbalance 0.10;
    nCellsBetweenLevels 2;

    features
    (
    );

    refinementSurfaces
    {
        barrel
        {
            level (2 2);
        }
        fins
        {
            level (2 3);
        }
        head
        {
            level (2 2);
        }
    }

    resolveFeatureAngle 30;

    refinementRegions
    {
    }

    locationInMesh (0.10 0.10 -0.05);
    allowFreeStandingZoneFaces false;
}

snapControls
{
    nSmoothPatch 3;
    tolerance 2.0;
    nSolveIter 30;
    nRelaxIter 5;

    nFeatureSnapIter 10;
    implicitFeatureSnap false;
    explicitFeatureSnap true;
    multiRegionFeatureSnap false;
}

addLayersControls
{
    relativeSizes true;
    layers
    {
    }
    expansionRatio 1.0;
    finalLayerThickness 0.3;
    minThickness 0.1;
    nGrow 0;
    featureAngle 60;
    nRelaxIter 3;
    nSmoothSurfaceNormals 1;
    nSmoothNormals 3;
    nSmoothThickness 10;
    maxFaceThicknessRatio 0.5;
    maxThicknessToMedialRatio 0.3;
    minMedialAxisAngle 90;
    nBufferCellsNoExtrude 0;
    nLayerIter 50;
}

meshQualityControls
{
    maxNonOrtho 65;
    maxBoundarySkewness 20;
    maxInternalSkewness 4;
    maxConcave 80;
    minVol 1e-13;
    minTetQuality 1e-15;
    minArea -1;
    minTwist 0.02;
    minDeterminant 0.001;
    minFaceWeight 0.05;
    minVolRatio 0.01;
    minTriangleTwist -1;
    nSmoothScale 4;
    errorReduction 0.75;
}

mergeTolerance 1e-6;
"""
open("system/snappyHexMeshDict","w").write(snappy)
print("wrote system/snappyHexMeshDict")

fvschemes = """FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
"""
open("system/fvSchemes","w").write(fvschemes)

fvsolution = """FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSolution;
}
solvers {}
relaxationFactors {}
"""
open("system/fvSolution","w").write(fvsolution)

